menv python -c 'from hera.analysis import open_run,sdh_onset; import numpy as np; from hera.analysis import resolve_channels,current_channel; 
for i in (5,6,7):
 r=open_run("data/"+str(i)); print(i, r.rows, r.cols); print("duration",np.ptp(r.col("time")),"dt",np.percentile(np.diff(r.col("time")),[10,50,90])); print(resolve_channels(r.meta))
 if i==5: continue
 ch=resolve_channels(r.meta); cur=current_channel(ch); v=next(c for c in ch if c.cid=="sr1"); R=(r.col(v.col)/v.gain)/(r.col(cur.col)/cur.gain); on=sdh_onset(R,r.col("magnet_field"),r_full_scale=5000); print(on.summary())'
